/* An AI-SDK-shaped surface: interfaces with primitive members, arrays of
 * interfaces, optional composite results, and options objects mixing
 * headers records, union-typed media inputs, and undefined-armed fields. */

export interface MediaFile {
  mediaType: string;
  size: number;
}

export interface GenResult {
  text: string;
  count: number;
  files?: MediaFile[];
  headers: Record<string, string> | undefined;
}

export interface GenOptions {
  model: string;
  prompt?: string;
  headers?: Record<string, string>;
  payload?: Uint8Array | string;
  source?: URL | Uint8Array;
  tag?: string | undefined;
}

export declare function generate(options: GenOptions): GenResult;
